// Selecciona la siguiente fila pendiente de la cola editorial.
// Criterio: primera fila cuyo campo Status esté vacío.
// Si todas tienen Status, no hay nada que generar y abortamos.

const items = $input.all();
if (!items.length) {
  return [];
}

// Encuentra primera fila SIN Status (o con Status vacío)
const pending = items.find((it) => {
  const status = (it.json.Status || it.json.status || '').toString().trim();
  return status === '';
});

if (!pending) {
  // No hay pendientes. Devolvemos array vacío para cortar el flujo.
  return [];
}

// Normalizamos los nombres de campo (las cabeceras del sheet pueden variar en
// acentos/mayúsculas; toleramos ambas variantes).
const row = pending.json;
const pick = (...keys) => {
  for (const k of keys) {
    if (row[k] !== undefined && row[k] !== null && row[k] !== '') return row[k];
  }
  return '';
};

return [{
  json: {
    rowNumber: pending.json.row_number || pending.json._rowNumber, // n8n inyecta uno de estos
    dia: pick('Día', 'Dia', 'day', 'Day'),
    keyword: pick('Palabra Clave Principal', 'Keyword', 'palabra clave principal'),
    intent: pick('Intención de Búsqueda', 'Intencion de Busqueda', 'Intent'),
    seoTitle: pick('Título SEO', 'Titulo SEO', 'SEO Title'),
    h2Structure: pick('Estructura H2 Sugerida', 'H2 Structure', 'estructura h2'),
    cta: pick('Call to Action (CTA)', 'CTA', 'Call to Action'),
    rawRow: row
  }
}];

// Transforma la salida JSON de Gemini en una mutación lista para Sanity.
// Construye el array `content` en formato Portable Text.

const sourceRow = $('Pick Next Pending Row').first().json;
const geminiResp = $input.first().json;

// El nodo nativo Google Gemini puede devolver el texto en distintos lugares
// según versión. Probamos los más habituales en orden.
let rawText =
  geminiResp?.content?.parts?.[0]?.text ??
  geminiResp?.content ??
  geminiResp?.text ??
  geminiResp?.response ??
  geminiResp?.candidates?.[0]?.content?.parts?.[0]?.text ??
  '';

if (typeof rawText !== 'string') {
  rawText = JSON.stringify(rawText);
}
rawText = rawText.trim();

if (!rawText) {
  throw new Error('No se pudo extraer texto de la respuesta de Gemini. Keys: ' + Object.keys(geminiResp || {}).join(','));
}

// Quita posibles wrappers ```json ... ```
rawText = rawText.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();

let data;
try {
  data = JSON.parse(rawText);
} catch (e) {
  throw new Error('La respuesta de Gemini no es JSON válido: ' + e.message + '\n---\n' + rawText.substring(0, 500));
}

// Validación mínima
const required = ['title', 'slug', 'excerpt', 'category', 'tags', 'readTime', 'metaTitle', 'metaDescription', 'keywords', 'blocks'];
for (const k of required) {
  if (data[k] === undefined || data[k] === null) {
    throw new Error(`Campo requerido ausente en la respuesta: ${k}`);
  }
}
if (!Array.isArray(data.blocks) || data.blocks.length < 3) {
  throw new Error('blocks debe ser un array con al menos 3 elementos');
}

// Helpers Portable Text
const key = () => Math.random().toString(36).slice(2, 14);

function textBlock(style, text) {
  return {
    _type: 'block',
    _key: key(),
    style,
    markDefs: [],
    children: [
      { _type: 'span', _key: key(), text, marks: [] }
    ]
  };
}

function highlightBlock(style, title, content) {
  return {
    _type: 'highlightBox',
    _key: key(),
    style: style || 'blue',
    title: title || '',
    content: content || ''
  };
}

const content = [];
for (const b of data.blocks) {
  switch (b.type) {
    case 'intro':
    case 'paragraph':
    case 'cta':
      if (b.text) content.push(textBlock('normal', b.text));
      break;
    case 'h2':
    case 'h3':
    case 'h4':
      if (b.text) content.push(textBlock(b.type, b.text));
      break;
    case 'blockquote':
      if (b.text) content.push(textBlock('blockquote', b.text));
      break;
    case 'highlightBox':
      content.push(highlightBlock(b.style, b.title, b.content));
      break;
  }
}

if (content.length === 0) {
  throw new Error('Tras transformar a Portable Text quedaron 0 bloques. Revisa la respuesta de Gemini.');
}

// _id en draft → Sanity lo crea como borrador
const rawSlug = (data.slug || '').toString().trim();
const safeSlug = rawSlug.length > 0 ? rawSlug.replace(/[^a-z0-9-]/gi, '-').toLowerCase() : 'post-' + Date.now();
const draftId = 'drafts.' + safeSlug + '-' + Math.random().toString(36).slice(2, 8);
const nowIso = new Date().toISOString();

return [{
  json: {
    sourceRowNumber: sourceRow.rowNumber,
    draftId,
    title: data.title,
    slug: safeSlug,
    sanityMutation: {
      mutations: [
        {
          create: {
            _type: 'blogPost',
            _id: draftId,
            title: data.title,
            slug: { _type: 'slug', current: safeSlug },
            excerpt: data.excerpt,
            status: 'pending_review',
            category: data.category,
            tags: data.tags || [],
            publishedAt: nowIso,
            readTime: data.readTime || '6 min',
            featured: false,
            content,
            seo: {
              metaTitle: (data.metaTitle || data.title).slice(0, 60),
              metaDescription: (data.metaDescription || data.excerpt).slice(0, 160),
              keywords: data.keywords || []
            }
          }
        }
      ]
    }
  }
}];

